@Test
public void testPlusMonthsEndOfMonthClampForward() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 31);
    LocalDate result = date.plusMonths(1);
    assertEquals("2024-01-31", result.toString());
}

@Test
public void testPlusMonthsEndOfMonthClampBackward() throws Exception {
    LocalDate date = new LocalDate(2024, 1, 31);
    LocalDate result = date.plusMonths(-1);
    assertEquals("2023-12-31", result.toString());
}

@Test
public void testPlusMonthsLargePositive() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(1200);
    assertEquals("2100-04-05", result.toString());
}

@Test
public void testPlusMonthsLargeNegative() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(-1200);
    assertEquals("1900-04-05", result.toString());
}

@Test
public void testPlusMonthsBoundaryYearStart() throws Exception {
    LocalDate date = new LocalDate(1900, 1, 1);
    LocalDate result = date.plusMonths(1);
    assertEquals("1900-02-01", result.toString());
}

@Test
public void testPlusMonthsBoundaryYearEnd() throws Exception {
    LocalDate date = new LocalDate(2100, 12, 31);
    LocalDate result = date.plusMonths(-1);
    assertEquals("2100-11-30", result.toString());
}
